require 'digest'
require 'nokogiri'
require 'uri'

# Version the emitted files, including CSS generated by Jekyll, rather than
# source timestamps. Returning browsers then request the code paired with a page.
module CoMPhyAssetFingerprints
  module_function

  def version_url(value, destination, hashes)
    url = URI.parse(value)
    return value if url.scheme || url.host || !url.path.start_with?('/assets/')
    return value unless url.path.match?(/\.(?:js|css)\z/)

    path = URI::DEFAULT_PARSER.unescape(url.path)
    raise ArgumentError, "unsafe asset path: #{value}" if path.split('/').any? { |part| %w[. ..].include?(part) }

    root = File.realpath(destination)
    asset = File.join(root, path.delete_prefix('/'))
    unless File.file?(asset) && File.realpath(asset) == asset
      raise ArgumentError, "missing or linked build asset: #{path}"
    end
    digest = hashes[asset] ||= Digest::SHA256.file(asset).hexdigest
    query = URI.decode_www_form(url.query || '').reject { |key, _| key == 'v' }
    url.query = URI.encode_www_form(query + [['v', digest]])
    url.to_s
  end

  def rewrite_destination(destination)
    hashes = {}
    changed = 0
    Dir.glob(File.join(destination, '**', '*.html')).sort.each do |path|
      original = File.read(path, encoding: 'UTF-8')
      document = Nokogiri::HTML(original, nil, 'UTF-8')
      modified = false
      document.css('script[src], link[href]').each do |node|
        if node.name == 'script'
          attribute = 'src'
        else
          next if (node['rel'].to_s.split & %w[stylesheet preload modulepreload]).empty?

          attribute = 'href'
        end
        before = node[attribute]
        after = version_url(before, destination, hashes)
        next if before == after

        node[attribute] = after
        modified = true
      end
      next unless modified

      File.write(path, document.to_html, encoding: 'UTF-8')
      changed += 1
    end
    changed
  end
end

Jekyll::Hooks.register :site, :post_write do |site|
  count = CoMPhyAssetFingerprints.rewrite_destination(site.dest)
  Jekyll.logger.info 'Asset fingerprints:', "updated #{count} built HTML pages"
end
